(()=>{'use strict';
const D=window.STEEL_DATA,L=window.SteelLogic,$=s=>document.querySelector(s),M=D.metadata;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const srcs=Object.fromEntries(D.sources.map(s=>[s.source_id,s])),cases=Object.fromEntries(D.cases.map(c=>[c.case_id,c])),eqs=Object.fromEntries(D.equipment.map(e=>[e.equipment_id,e]));
const names={overview:'证据总览',routes:'工艺路线',evidence:'参数证据',models:'模型与公式',sources:'来源文献',downloads:'核心数据包'};
const state={page:'overview',evidence:{q:'',process:'',tag:'',kind:'',case_id:'',core:true,page:1},modelFilter:'all',route:null,sourceQ:''};
const tags={R:['原文值','green'],D:['换算值','blue'],A:['作者模型/假设','gray'],F:['拟合/推荐','amber'],U:['待核隔离','red']};
const badge=(text,color='gray')=>`<span class="badge ${color}">${esc(text)}</span>`;
const tag=o=>badge(`${o.evidence_tag} · ${tags[o.evidence_tag][0]}`,tags[o.evidence_tag][1]);
const sourceButton=id=>`<button class="source-button" data-source="${esc(id)}">${esc(id)}</button>`;
const sourcesList=ids=>ids.length?ids.map(sourceButton).join(' &nbsp; '):'<span class="small-note">守恒 / 几何推导</span>';
const heading=(en,title,desc,right='')=>`<div class="page-head"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${desc}</p></div>${right}</div>`;
const pill=()=>'<span class="pill"><i></i>研究版本 · 可追溯</span>';
const formatBytes=b=>b>1048576?`${(b/1048576).toFixed(1)} MB`:`${Math.ceil(b/1024)} KB`;
const fileInfo=name=>D.downloads.find(f=>f.name===name);
const processLabels={TAP:'出钢',LF:'钢包精炼',SOFT:'软吹',TRANSFER:'转运',TD:'中间包',CC:'连铸',RH:'真空循环',RHOB:'吹氧脱碳',WIRE:'喂丝',AR:'吹氩',VD:'真空脱气'};
function strip(steps){return `<div class="process-strip">${steps.map((id,i)=>`${i?'<span class="step-arrow" aria-hidden="true">→</span>':''}<button class="step-box ${id==='LF'||id==='RH'||id==='RHOB'?'focus':''}" data-equipment="${id}" aria-label="查看${esc(eqs[id]?.name||id)}"><strong>${id==='TRANSFER'?'TR':id}</strong><small>${esc(processLabels[id]||eqs[id]?.name||id)}</small></button>`).join('')}</div>`}
function row(o){const excluded=!o.core_reference;return `<tr><td><button class="record-button" data-record="${o.observation_id}">${o.observation_id}</button></td><td><span class="mono">${esc(o.grade)}</span><span class="param-sub">${esc(o.process)} · ${esc(o.case_id)}</span></td><td class="param-cell">${esc(L.label(o.parameter))}<span class="param-sub">${esc(o.parameter)}</span></td><td class="mono">${esc(L.valueText(o))}</td><td class="mono">${esc(o.unit)}</td><td>${tag(o)}${excluded?`<span class="param-sub">${esc(o.exclusion_reason)}</span>`:''}</td><td>${sourceButton(o.source_id)}</td><td><button class="button slim" data-record="${o.observation_id}">详情 ↗</button></td></tr>`}
function table(rows,id=''){return `<div class="table-wrap"><table class="data-table" ${id?`id="${id}"`:''}><thead><tr><th>记录</th><th>钢种 / 工况</th><th>参数指标</th><th>原文数值 / 范围</th><th>原始单位</th><th>证据性质</th><th>来源</th><th>追溯</th></tr></thead><tbody>${rows.map(row).join('')}</tbody></table></div>`}
function overview(){
  const featured=['lime_after','Ti_addition_oxygen_max','argon_volume','temperature','ordinary_target_C_max'];
  const rows=featured.map(p=>D.observations.find(o=>o.parameter===p&&o.core_reference&&(p!=='argon_volume'||o.case_id==='S355H16'))).filter(Boolean);
  const years=Array.from({length:10},(_,i)=>2017+i).map(y=>[y,D.sources.filter(s=>s.publication_year===y).length]);
  return heading('EVIDENCE / OVERVIEW','把工艺参数，放回它的证据里。','面向普钢出钢后精炼，串联工艺路线、参数工况与动力学模型。每一条数值，都保留来源与适用边界。',pill())+
  `<div class="lead-band"><span class="band-title">核心参考集已就绪</span><span class="band-detail">排除 ${M.historical_records} 条历史复用和 ${M.quarantined_records} 条待核记录；保留完整底稿。</span><a href="#downloads">查看数据包 →</a></div>
  <div class="stats-grid">${[[M.core_records,'核心参考参数','完整底稿 '+M.all_records+' 条 · 原文定位可查','01'],[D.sources.length,'可追溯来源','论文 / 钢厂公开资料 / 设备说明','02'],[D.models.length,'模型与公式','21 已实现计算 · 5 待实现','03'],[M.industrial_heats,'同源工业炉次','其余为统计、模型工况或控制目标','04']].map(([n,t,f,i])=>`<div class="stat"><span class="stat-index">${i}</span><div class="stat-label">${t}</div><div class="stat-value">${n}<small>${i==='02'?'条':i==='04'?'炉':'项'}</small></div><div class="stat-foot">${f}</div></div>`).join('')}</div>
  <div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>从出钢到浇注，沿路线追溯</h2><small>先确认目标钢种，再选择适合的处理路径</small></div><a class="text-link" href="#routes">全部路线 →</a></div><div class="route-demo"><div class="route-label"><span><b>Q355B</b> · Ti 微合金化参考路线</span>${badge('原文工艺案例','green')}</div>${strip(['TAP','LF','SOFT','TRANSFER','TD','CC'])}<p class="route-note"><b>关键控制：</b>加钛前氧活度、渣碱度及硫含量需要联动考虑。案例参数不等于牌号通用配方。</p></div><div class="case-preview"><span class="mono">S06 / Q355Ti</span><span>宝武鄂城 · 工业优化研究</span><a href="#evidence?case=Q355Ti">查看参数 ↗</a></div></section>
  <section class="panel"><div class="panel-head"><div><h2>覆盖情况，一眼看清</h2><small>有数据的范围与仍待补足的部分分开呈现</small></div></div><div class="panel-body"><div class="coverage-item"><i class="coverage-dot"></i><div><strong>结构钢 / 热轧板带 / IF</strong><p>Q355B、S355、SPHC与IF路线有定量工况。</p></div>${badge('已入库','green')}</div><div class="coverage-item"><i class="coverage-dot"></i><div><strong>LF / RH / VD 动力学</strong><p>传质、混匀、循环、脱硫、脱气及热平衡。</p></div>${badge('可追溯','green')}</div><div class="coverage-item"><i class="coverage-dot amber"></i><div><strong>全产品族与工业精度</strong><p>目录覆盖15类；跨厂预测仍需补数和校准。</p></div>${badge('待扩展','amber')}</div></div></section></div>
  <div class="section-row"><h2>核心参数速览<small>原始单位与证据类型同时保留</small></h2><a class="text-link" href="#evidence">浏览 ${M.core_records} 条核心参考 →</a></div><section class="panel">${table(rows)}<div class="table-footer"><span>R 不自动等于工业实测；企业目标、模型输入和测量值分别标记。</span><a href="#evidence">查看完整证据链 ↗</a></div></section>
  <div class="overview-bottom"><section class="panel"><div class="panel-head"><div><h2>已收录来源的年份分布</h2><small>检索窗口 2016.10—2026.10 · 按卷期年统计</small></div>${badge('定向采样','gray')}</div><div class="panel-body"><div class="year-chart" role="img" aria-label="${years.map(([y,n])=>`${y}年${n}条来源`).join('，')}">${years.map(([y,n])=>`<div class="year-col"><span class="year-n">${n}</span><div class="year-bar" style="height:${n*13}px"></div><span class="year-label">${String(y).slice(-2)}</span></div>`).join('')}</div><p class="chart-note">含部分仅元数据条目；2条无日期设备商资料未计入。尚非十年穷尽统计。</p></div></section>
  <section class="panel"><div class="panel-head"><div><h2>一份可以继续建模的数据包</h2><small>数据库、表格、原文链接和公式说明放在一起</small></div></div><div class="panel-body"><div class="download-feature"><div class="pack-visual">.zip</div><div><h3>普钢精炼 · 核心支持包</h3><p>SQLite + CSV + JSON + Python<br>含字段说明、单位换算、审计与校验清单</p></div></div><div class="button-row"><a class="button primary" download href="downloads/core-support-pack.zip">下载核心包 <span>↓</span></a><a class="button" href="#downloads">查看全部文件</a></div></div></section></div>`;
}
function evidence(){const f=state.evidence;return heading('EVIDENCE / PARAMETERS','参数证据','按钢种、工序和证据性质筛选。原始数据、SI换算、研究背景与原文定位可以逐项追溯。',pill())+
 `<div class="filter-panel"><div class="field wide"><label for="evidence-q">关键词</label><input id="evidence-q" value="${esc(f.q)}" placeholder="如：Q355B、硫、氩气、S06"></div><div class="field"><label for="evidence-process">工序</label><select id="evidence-process"><option value="">全部工序</option>${['LF','RH','VD','tundish-CC','soft-stirring','CC','BOF-LF-CC'].map(p=>`<option ${f.process===p?'selected':''} value="${p}">${p}</option>`).join('')}</select></div><div class="field"><label for="evidence-tag">证据性质</label><select id="evidence-tag"><option value="">全部类型</option>${Object.entries(tags).map(([k,v])=>`<option value="${k}" ${f.tag===k?'selected':''}>${k} · ${v[0]}</option>`).join('')}</select></div><label class="checkbox"><input type="checkbox" id="evidence-core" ${f.core?'checked':''}>仅核心参考集</label><button class="button" id="reset-filters">重置</button></div>
 <div class="legend">${Object.entries(tags).map(([k,v])=>`<span>${badge(k,v[1])}${v[0]}</span>`).join('')}<span>“核心参考”仍需核对设备与工况，不是生产设定。</span></div><div id="evidence-summary" class="filter-summary" aria-live="polite"></div><section class="panel"><div id="evidence-results"></div><div id="evidence-pagination" class="table-footer"></div></section>`}
function updateEvidence(){const f=state.evidence,rows=L.filterEvidence(D.observations,f),size=20,pages=Math.max(1,Math.ceil(rows.length/size));f.page=Math.max(1,Math.min(f.page,pages));const page=rows.slice((f.page-1)*size,f.page*size);$('#evidence-summary').innerHTML=`<span>找到 <b>${rows.length}</b> 条参数 ${f.case_id?`· 工况 ${esc(f.case_id)} <button class="button slim" id="clear-case">清除工况</button>`:''}</span><button class="button slim" id="export-filtered">导出当前筛选 CSV ↓</button>`;$('#evidence-results').innerHTML=page.length?table(page):'<div class="empty"><strong>没有匹配的参数</strong><p>尝试其他关键词，或取消“仅核心参考集”查看历史及待核记录。</p></div>';$('#evidence-pagination').innerHTML=`<span>${rows.length?`${(f.page-1)*size+1}–${Math.min(f.page*size,rows.length)}`:'0'} / ${rows.length} 条</span><div class="pager"><button class="button slim" data-page="prev" ${f.page<=1?'disabled':''}>上一页</button><span>${f.page} / ${pages}</span><button class="button slim" data-page="next" ${f.page>=pages?'disabled':''}>下一页</button></div>`}
function routes(){const selected=D.routes.find(r=>r.route_id===state.route)||D.routes[0];state.route=selected.route_id;return heading('PROCESS / ROUTES','工艺路线','连接目标产品、设备功能与参数证据。已记录的工业路线和待验证的工程候选分别标记。',pill())+
 `<div class="two-column"><div class="route-list">${D.routes.map(r=>`<button class="route-card ${r.route_id===selected.route_id?'selected':''}" data-route="${r.route_id}"><span class="mono">${r.route_id} / ${r.grade_id}</span><h3>${esc(D.grade_families.find(g=>g.grade_id===r.grade_id)?.name||r.grade_id)}</h3><p>${r.steps.filter(s=>!['TRANSFER','SOFT','TD'].includes(s)).join(' → ')}</p></button>`).join('')}</div><section class="panel route-detail"><div class="eyebrow">${selected.route_id} · PROCESS CHAIN</div><h2>${esc(D.grade_families.find(g=>g.grade_id===selected.grade_id)?.name||'工艺路线')}</h2>${badge(selected.status==='evidence_route'?'文献工艺案例':selected.status==='partial_evidence_route'?'部分文献证据':'工程候选 · 待验证',selected.status==='evidence_route'?'green':'amber')}${strip(selected.steps)}<div class="callout">${esc(selected.selection_rule)}</div><div class="detail-grid"><div class="detail-box"><h3>路线依据</h3>${sourcesList(selected.source_ids)}</div><div class="detail-box"><h3>质量判断的起点</h3><p>同时输入钢水状态、目标钢种、设备能力与连铸计划，才能确定路线。</p></div></div><h3 style="margin:26px 0 10px">各工位的温度与时间约束</h3>${selected.steps.map(id=>`<div class="keyvalue"><dt><button class="record-button" data-equipment="${id}">${id}</button></dt><dd><b>${esc(eqs[id]?.name||id)}</b><br>${esc(eqs[id]?.temperature_rule||'待核')}<br><span class="small-note">${esc(eqs[id]?.time_rule||'待核')}</span></dd></div>`).join('')}<div class="button-row"><button class="button primary" id="route-evidence">查看关联参数 →</button></div></section></div>`}
function models(){return heading('KINETICS / MODEL LIBRARY','模型与公式','从质量守恒到传质与循环，保留推导、输入单位和适用域。公式实现与工业验证是两个不同状态。',pill())+
 `<div class="lead-band"><span class="band-title">21 个模型条目已有计算实现</span><span class="band-detail">5 个模块仍待实现；当前没有目标钢厂的已拟合标定。</span><a href="downloads/model-guide.md" download>下载完整推导 ↓</a></div><div class="tabs" role="group" aria-label="模型状态筛选">${[['all','全部 26'],['implemented','已实现计算 21'],['design','待实现 5']].map(([k,t])=>`<button class="tab ${state.modelFilter===k?'active':''}" data-model-filter="${k}">${t}</button>`).join('')}</div>
 <div class="models-grid">${D.models.filter(md=>state.modelFilter==='all'||(state.modelFilter==='implemented'?md.status==='implemented_unvalidated':md.status!=='implemented_unvalidated')).map(md=>`<button class="model-card" data-model="${md.model_id}"><div class="model-top"><span class="eyebrow">${md.model_id}</span>${badge(md.status==='implemented_unvalidated'?'已实现 · 待工业验证':'待实现',md.status==='implemented_unvalidated'?'blue':'amber')}</div><h3>${esc(md.name)}</h3><div class="formula">${esc(md.equation)}</div><p>${esc(md.domain)}</p><div class="model-bottom"><span class="mono">${esc(md.output_units)}</span><span>查看推导与输入 ↗</span></div></button>`).join('')}</div>
 <section class="calculator" id="sulfur-calculator"><div class="calculator-head"><div><div class="eyebrow">M07 / CONDITIONAL SCENARIO</div><h2 style="margin-top:7px">有限渣量脱硫 · 条件计算</h2><p>修改参数查看结果与平衡边界。初始工况和速率均为演示假设，不是文献实测炉次。</p></div>${badge('假设情景 · 非生产推荐','amber')}</div><form id="calc-form"><div class="calc-grid">${[['Mm','钢水质量 / t',100],['Ms','渣质量 / t',1.5],['wm','钢中初始硫 / ppm',200],['ws','渣中初始硫 / wt%',0.1],['Lw','硫分配比 Lw',100],['gamma','集总传质速率 γ / s⁻¹',0.001],['t','处理时间 / min',10]].map(([id,l,v])=>`<div class="field"><label for="calc-${id}">${l}</label><input type="number" id="calc-${id}" name="${id}" value="${v}" step="any" required></div>`).join('')}<div class="field"><label>&nbsp;</label><button class="button primary" type="submit">计算条件结果 →</button></div></div></form><div id="calc-output" aria-live="polite"></div></section>`}
function runCalc(){try{const val=id=>Number($('#calc-'+id).value);for(const id of ['Mm','Ms','wm','ws','Lw','gamma','t'])if($('#calc-'+id).value.trim()==='')throw Error('请填写全部输入参数');const p={Mm:val('Mm')*1000,Ms:val('Ms')*1000,wm:val('wm')*1e-6,ws:val('ws')/100,Lw:val('Lw'),gamma:val('gamma'),t:val('t')*60};const r=L.sulfur(p);const points=Array.from({length:41},(_,i)=>{const t=p.t*i/40;return [55+i*10,L.sulfur({...p,t}).steel*1e6]});const max=Math.max(p.wm,r.eq)*1e6*1.12||1;const y=c=>135-c/max*110;const path=points.map(([x,c],i)=>`${i?'L':'M'}${x.toFixed(2)},${y(c).toFixed(2)}`).join(' ');$('#calc-output').innerHTML=`<div class="calc-result"><div><div class="small-note">${L.fmt(val('t'))} min 后的条件计算值</div><div class="calc-number">${L.fmt(r.steel*1e6)}<small>ppm S</small></div><div class="calc-detail">有限渣量平衡边界：${L.fmt(r.eq*1e6)} ppm<br>总硫质量守恒误差：${r.residual.toExponential(2)} kg<br>这些数值不是经工业校准的终点预测。</div></div><svg class="plot" viewBox="0 0 480 170" role="img" aria-label="硫含量随时间变化的假设情景，终点${r.steel*1e6}ppm"><line x1="55" y1="135" x2="455" y2="135" stroke="#d7dfd3"/><line x1="55" y1="15" x2="55" y2="135" stroke="#d7dfd3"/><line x1="55" y1="${y(r.eq*1e6)}" x2="455" y2="${y(r.eq*1e6)}" stroke="#ba9665" stroke-dasharray="4 5"/><path d="${path}" stroke="#3c7963" stroke-width="2.5" fill="none"/><text x="5" y="18">S / ppm</text><text x="50" y="156">0</text><text x="400" y="156">${L.fmt(val('t'))} min</text><text x="340" y="${Math.max(20,y(r.eq*1e6)-7)}">平衡边界</text></svg></div><p class="small-note">模型依据：有限渣量钢渣硫守恒（M07）。γ 需要由 k、A、V 或同工况浓度序列独立确定，不能仅凭吹氩量填写。</p>`}catch(e){$('#calc-output').innerHTML=`<div class="calc-error">${esc(e.message)}</div>`}}
function sources(){return heading('PROVENANCE / SOURCES','来源文献','每条来源记录访问层级、出版年与原始数据年代。统计摘要、数值模型与工业逐炉数据不能等同使用。',pill())+`<div class="filter-panel"><div class="field wide"><label for="source-q">查找文献</label><input id="source-q" value="${esc(state.sourceQ)}" placeholder="输入标题、DOI、钢种或来源编号"></div><span class="small-note">36 条来源 · 含2条无日期设备资料</span></div><div id="source-results" class="source-grid"></div>`}
function updateSources(){const q=state.sourceQ.toLowerCase();const list=D.sources.filter(s=>[s.source_id,s.title,s.scope,s.doi,s.note].join(' ').toLowerCase().includes(q));$('#source-results').innerHTML=list.length?list.map(s=>{const n=D.observations.filter(o=>o.source_id===s.source_id).length;return `<article class="source-card"><div class="source-card-head"><span class="mono">${s.source_id} · ${s.publication_year||'无日期'}</span>${badge(n?`${n} 条参数`:'目录 / 能力说明',n?'green':'gray')}</div><h3>${esc(s.title)}</h3><p>${esc(s.scope)}</p><p>访问层级：${esc(s.access_level)}<br>原始数据年代：${esc(s.original_data_vintage)}</p><div class="source-card-footer"><button class="source-button" data-source="${s.source_id}">来源详情 ↗</button><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">原始页面 ↗</a></div></article>`}).join(''):'<div class="empty"><strong>没有匹配的来源</strong><p>试试钢种、DOI或不同的关键词。</p></div>'}
function safeUrl(url){return /^https?:\/\//i.test(url)?esc(url):'#'}
function downloads(){const zip=fileInfo('core-support-pack.zip');return heading('RESOURCES / DATA PACKAGE','核心数据支持包','把证据、结构与计算方法一起带走。网页展示与下载文件来自同一个数据库快照。',pill())+
 `<section class="download-hero"><div><div class="eyebrow">CORE SUPPORT PACK / VERSION 0.1</div><h2>为工艺研究准备的数据底座。</h2><p>核心参考 ${M.core_records} 条，完整底稿 ${M.all_records} 条。包含SQLite数据库、CSV/JSON、来源链接、公式推导和数据质量说明，便于继续筛选、建模与扩充。</p><div class="button-row"><a class="button primary" download href="downloads/core-support-pack.zip">下载核心支持包 <span>↓</span></a><span class="small-note" style="align-self:center">ZIP · ${formatBytes(zip.bytes)}</span></div></div><div class="package-files"><div>core.sqlite <span>关系数据库</span></div><div>core-observations.csv <span>${M.core_records} 条核心参考</span></div><div>all-observations.csv <span>${M.all_records} 条完整底稿</span></div><div>core-data.json <span>应用与建模输入</span></div><div>model-guide.md <span>公式、推导与边界</span></div><div>manifest.json <span>SHA-256校验</span></div></div></section>
 <div class="download-list">${[['core.sqlite','核心参考数据库','SQLite · 保留来源和工况关系'],['core-observations.csv','核心参考参数表','CSV · 可用Excel直接打开'],['all-observations.csv','完整原始参数底稿','CSV · 含历史与待核条目'],['sources.csv','来源目录','CSV · 原始链接、年份与访问层级'],['models.csv','模型公式注册表','CSV · 输入、来源和适用条件'],['core-data.json','结构化核心数据','JSON · 用于网页与后续建模'],['model-guide.md','动力学公式与推导','Markdown · 含可识别性说明'],['quality-audit.md','数据质量审计报告','Markdown · 缺口、单位与隔离项'],['quarantined.csv','待核隔离记录','CSV · 不用于参数推荐'],['complete-database.zip','完整数据库与计算源码','ZIP · 含Python与43项原有测试']].map(([file,title,desc])=>`<article class="download-row"><div class="file-extension">${file.split('.').pop().toUpperCase()}</div><div><h3>${title}</h3><p>${desc} · ${formatBytes(fileInfo(file)?.bytes||0)}</p></div><a class="button slim" download href="downloads/${file}" aria-label="下载${title}">下载 ↓</a></article>`).join('')}</div>
 <div class="callout amber"><b>正确使用这个数据包</b><br>${esc(M.definition)} 文献中出现的大样本数量是作者的研究规模，并不表示本包拥有相应的逐炉原始数据。当前尚未完成十年穷尽统计，也没有跨厂工业验证精度。</div><section class="panel"><div class="panel-head"><h2>文件一致性与版本</h2><a href="downloads/manifest.json" class="text-link" download>下载校验清单 ↓</a></div><div class="panel-body"><p class="small-note">核心包SHA-256</p><code style="font-size:10px;overflow-wrap:anywhere">${zip.sha256}</code><p class="small-note" style="margin-top:14px">来源数据库SHA-256</p><code style="font-size:10px;overflow-wrap:anywhere">${M.source_database_sha256}</code></div></section>`}
function key(k,v){return `<div class="keyvalue"><dt>${esc(k)}</dt><dd>${v}</dd></div>`}
function showDialog(type,html){$('#dialog-type').textContent=type;$('#dialog-content').innerHTML=html;const dia=$('#detail-dialog');if(!dia.open)dia.showModal();dia.scrollTop=0}
function showRecord(id){const o=D.observations.find(x=>x.observation_id===id);if(!o)return;const c=cases[o.case_id];showDialog('PARAMETER / '+id,`<h2 id="dialog-title">${esc(L.label(o.parameter))}</h2><div class="evidence-tag-row">${tag(o)}${badge(o.core_reference?'核心参考':'非核心 · '+o.exclusion_reason,o.core_reference?'green':'amber')}${badge(L.kinds[o.study_kind]||o.study_kind)}</div>${key('原文数值',`<span class="mono">${esc(L.valueText(o))} ${esc(o.unit)}</span>`)}${key('钢种 / 工序',esc(o.grade)+' / '+esc(o.process))}${key('工况',`<span class="mono">${esc(o.case_id)}</span>`)}${key('数量性质',esc(o.quantity_role))}${key('原文定位',esc(o.locator))}${key('SI换算',`${esc(o.si_value!==null?L.fmt(o.si_value):`${L.fmt(o.si_lower)} – ${L.fmt(o.si_upper)}`)} ${esc(o.si_unit)}`)}${key('换算基准',esc(o.reference_basis))}${key('原始来源',`${sourceButton(o.source_id)} · <a href="${safeUrl(o.url)}" target="_blank" rel="noopener noreferrer">打开原始页面 ↗</a>`)}${key('原始数据年代',esc(o.original_data_vintage))}${key('核验状态',esc(o.review_status))}<h3>同一工况的背景</h3><div class="context-json">${esc(JSON.stringify(c.context,null,2))}</div>${o.note?`<div class="callout amber">${esc(o.note)}</div>`:''}<div class="button-row"><button class="button" data-case="${o.case_id}">浏览同工况全部参数 →</button></div>`)}
function showSource(id){const s=srcs[id];if(!s)return;const n=D.observations.filter(o=>o.source_id===id).length;showDialog('SOURCE / '+id,`<h2 id="dialog-title">${esc(s.title)}</h2>${key('来源ID',esc(id))}${key('DOI',esc(s.doi||'未提供 / 待核'))}${key('卷期年 / 首次公开',`${esc(s.publication_year||'无日期')} / ${esc(s.publication_date||'未核至具体日期')}`)}${key('日期精度',esc(s.date_precision))}${key('访问层级',esc(s.access_level))}${key('原始数据年代',esc(s.original_data_vintage))}${key('研究范围',esc(s.scope))}${key('提取参数',`${n} 条（不等于独立炉次数）`)}${key('原始链接',`<a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">打开原始页面 ↗</a>`)}<div class="callout">${esc(s.note||'使用前仍需核对原文工况与设备适用范围。')}</div><div class="button-row"><button class="button" data-source-evidence="${id}">浏览该来源参数 →</button></div>`)}
function showModel(id){const md=D.models.find(x=>x.model_id===id);if(!md)return;showDialog('MODEL / '+id,`<h2 id="dialog-title">${esc(md.name)}</h2><div class="evidence-tag-row">${badge(md.status==='implemented_unvalidated'?'已实现计算 · 待工业验证':'待实现设计','amber')}</div><div class="formula">${esc(md.equation)}</div>${key('输入变量',esc(md.inputs.join(', ')))}${key('输出单位',esc(md.output_units))}${key('计算实现',`<code>${esc(md.implementation)}</code>`)}${key('文献依据',sourcesList(md.source_ids))}<h3>公式推导</h3><p>${esc(md.derivation)}</p><h3>适用范围与限制</h3><div class="callout amber">${esc(md.domain)}</div>${id==='M07'?'<div class="button-row"><button class="button" id="jump-calc">打开条件计算器 →</button></div>':''}<div class="button-row"><a class="button" href="downloads/model-guide.md" download>下载完整公式说明 ↓</a></div>`)}
function showEquipment(id){const e=eqs[id];if(!e)return;showDialog('EQUIPMENT / '+id,`<h2 id="dialog-title">${esc(e.name)}</h2>${key('功能',esc(e.functions))}${key('范围',esc(e.scope))}${key('温度处理',esc(e.temperature_rule))}${key('时间处理',esc(e.time_rule))}${key('依据',sourcesList(e.source_ids))}<div class="callout">设备目录说明了要考虑的边界，不代表已有完整运行规程或跨钢种通用温度、时间设定。</div>`)}
function navigate(){const [name,query='']=location.hash.slice(1).split('?');state.page=names[name]?name:'overview';const p=new URLSearchParams(query);if(state.page==='evidence'&&p.has('case'))state.evidence={...state.evidence,case_id:p.get('case'),q:'',page:1};render()}
function render(){document.title=names[state.page]+' · 精炼数据支持库';$('#crumb').textContent=names[state.page];document.querySelectorAll('[data-nav]').forEach(a=>{const yes=a.dataset.nav===state.page;a.classList.toggle('active',yes);yes?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});$('#main').innerHTML=({overview,evidence,routes,models,sources,downloads}[state.page])();if(state.page==='evidence'){updateEvidence();for(const [id,key]of [['evidence-q','q'],['evidence-process','process'],['evidence-tag','tag'],['evidence-core','core']])$('#'+id).addEventListener(id==='evidence-q'?'input':'change',e=>{state.evidence[key]=key==='core'?e.target.checked:e.target.value;state.evidence.page=1;updateEvidence()})}if(state.page==='sources'){$('#source-q').addEventListener('input',e=>{state.sourceQ=e.target.value;updateSources()});updateSources()}if(state.page==='models'){$('#calc-form').addEventListener('submit',e=>{e.preventDefault();runCalc()});runCalc()}}
function goEvidence(change){Object.assign(state.evidence,{q:'',case_id:'',page:1},change);if($('#detail-dialog').open)$('#detail-dialog').close();if(location.hash==='#evidence'){state.page='evidence';render()}else location.hash='evidence'}
function downloadFiltered(){const rows=L.filterEvidence(D.observations,state.evidence),blob=new Blob([L.csv(rows)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`精炼参数_筛选_${rows.length}条.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(`已导出 ${rows.length} 条参数，包含原始来源链接`)}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.record)showRecord(b.dataset.record);else if(b.dataset.source)showSource(b.dataset.source);else if(b.dataset.model)showModel(b.dataset.model);else if(b.dataset.equipment)showEquipment(b.dataset.equipment);else if(b.dataset.case)goEvidence({case_id:b.dataset.case});else if(b.dataset.sourceEvidence)goEvidence({q:b.dataset.sourceEvidence,core:false});else if(b.dataset.route){state.route=b.dataset.route;render()}else if(b.dataset.modelFilter){state.modelFilter=b.dataset.modelFilter;render()}else if(b.dataset.page){state.evidence.page+=b.dataset.page==='next'?1:-1;updateEvidence()}else if(b.id==='reset-filters'){state.evidence={q:'',process:'',tag:'',kind:'',case_id:'',core:true,page:1};render()}else if(b.id==='clear-case'){state.evidence.case_id='';render()}else if(b.id==='export-filtered')downloadFiltered();else if(b.id==='route-evidence'){const r=D.routes.find(x=>x.route_id===state.route);goEvidence({q:r.source_ids[0]||r.grade_id,core:true})}else if(b.id==='jump-calc'){$('#detail-dialog').close();$('#sulfur-calculator')?.scrollIntoView({behavior:'smooth',block:'start'})}});
$('#dialog-close').addEventListener('click',()=>$('#detail-dialog').close());$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#global-form').addEventListener('submit',e=>{e.preventDefault();goEvidence({q:$('#global-search').value,core:false})});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#detail-dialog').open)$('#detail-dialog').close();$('#global-search').focus()}});
window.addEventListener('hashchange',()=>{navigate();window.scrollTo({top:0,behavior:'instant'})});navigate();
})();
